CREATE TABLE IF NOT EXISTS saved_freelancers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, employer_id BIGINT UNSIGNED NOT NULL, freelancer_id BIGINT UNSIGNED NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_saved_freelancer(employer_id,freelancer_id));
CREATE TABLE IF NOT EXISTS saved_jobs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, freelancer_id BIGINT UNSIGNED NOT NULL, job_id BIGINT UNSIGNED NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_saved_job(freelancer_id,job_id));